def _mode(seq):
    return Counter(seq).most_common(1)[0][0]

def transform(grid):
    h, w = len(grid), len(grid[0])
    base = _mode(v for row in grid for v in row)
    # The repeated background fills each large cell; separator bands have a
    # different modal color. Plain uniform outer margins are not part of image.
    rows = [r for r in range(h) if _mode(grid[r]) != base]
    cols = [c for c in range(w) if _mode([grid[r][c] for r in range(h)]) != base]
    while rows and len(set(grid[rows[0]])) == 1:
        rows.pop(0)
    while rows and len(set(grid[rows[-1]])) == 1:
        rows.pop()
    while cols and len({grid[r][cols[0]] for r in range(h)}) == 1:
        cols.pop(0)
    while cols and len({grid[r][cols[-1]] for r in range(h)}) == 1:
        cols.pop()
    out = []
    for r0, r1 in zip(rows, rows[1:]):
        outrow = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            v = corners[0]
            outrow.append(v if all(x == v for x in corners) else base)
